import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation
from scipy.optimize import minimize
sys.path.insert(0,'/opt/tools');import rcb_dtb
s=rcb_dtb.Session('/app/instance.json');m=s.model;d=s.data;adr=m.jnt_qposadr[m.joint('object_free_joint').id]
for k in [12,13,14,18,22]:
 g=np.array(s.goals[k]);Rg=Rotation.from_quat(g[3:]);
 def calc(x):
  p=g[:3]+x[:3];R=Rotation.from_rotvec(x[3:])*Rg;q=R.as_quat();d.qpos[adr:adr+7]=[*p,q[3],*q[:3]];mujoco.mj_forward(m,d)
  cs=[]
  for i in range(d.ncon):
   c=d.contact[i];n1=m.geom(c.geom1).name;n2=m.geom(c.geom2).name
   if ('bowl_' in n1 or 'bowl_' in n2) and ('object_object' in n1 or 'object_object' in n2):cs.append(c.dist)
  return rcb_dtb.keypoint_distance(p,np.r_[q[3],q[:3]],g), min(cs,default=.01)
 def f(x):
  dist,pen=calc(x);return dist+100*max(0,-pen-.001)**2
 best=None
 for i in range(5):
  x0=np.random.default_rng(i).normal(0,.01,6) if i else np.zeros(6)
  res=minimize(f,x0,method='Nelder-Mead',options={'maxiter':500,'xatol':1e-5})
  out=(res.fun,calc(res.x),res.x)
  if best is None or out[0]<best[0]:best=out
 print(k,'desired',calc(np.zeros(6)),'best',best,flush=True)
