import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation
from scipy.optimize import minimize
sys.path.insert(0,'/opt/tools');import rcb_dtb
s=rcb_dtb.Session('/app/instance.json');m=s.model;d=s.data;adr=m.jnt_qposadr[m.joint('object_free_joint').id];names=[m.geom(i).name for i in range(m.ngeom)]
for k in [13,14,15,16,17]:
 g=np.array(s.goals[k]);Rg=Rotation.from_quat(g[3:]);
 def calc(x):
  p=g[:3]+x[:3];q=(Rotation.from_rotvec(x[3:])*Rg).as_quat();d.qpos[adr:adr+7]=[*p,q[3],*q[:3]];mujoco.mj_forward(m,d)
  cs=[c.dist for c in d.contact[:d.ncon] if ('bowl_' in names[c.geom1] or 'bowl_' in names[c.geom2]) and ('object_object' in names[c.geom1] or 'object_object' in names[c.geom2])]
  return rcb_dtb.keypoint_distance(p,np.r_[q[3],q[:3]],g),min(cs,default=.01)
 for w in [500,2000]:
  def f(x):
   dd,pen=calc(x);return dd+w*max(0,-pen-.001)**2
  best=None
  for i in range(8):
   st=np.random.default_rng(i+100).normal(0,.01,6) if i else np.zeros(6)
   res=minimize(f,st,method='Nelder-Mead',options={'maxiter':600,'xatol':1e-5})
   out=(res.fun,calc(res.x),res.x)
   if best is None or out[0]<best[0]:best=out
  print(k,w,'best',best[1],best[2].round(4),flush=True)
